1	// «Мины»: поле 5 × 5, игрок выбирает число мин m (1…24, по умолчанию 3); мины расставляются в start за m вызовов rng,
2	// игрок открывает клетки и забирает выигрыш.
3	// Спецификация: games/mines/spec.md. Решения: decisions/mines.md (D-002…D-007, D-009, D-019…D-023). Документация: games/mines/README.md.
4	import type { GameModule, Rng, Step } from '../../../platform/sdk/types.ts';
5	import { GameError } from '../../../platform/sdk/types.ts';
6	
7	/** Число клеток поля 5 × 5 (D-002). */
8	export const CELL_COUNT = 25;
9	
10	/** Наименьшее допустимое число мин (D-019). */
11	export const MIN_MINES = 1;
12	
13	/** Наибольшее допустимое число мин (D-019). */
14	export const MAX_MINES = 24;
15	
16	/** Число мин, если игрок его не выбрал (D-019). */
17	export const DEFAULT_MINES = 3;
18	
19	/** Доля выплаты после house edge 2 %, в процентах — целое число для точного округления (D-021). */
20	export const RTP_PERCENT = 98;
21	
22	/** Нормализованные параметры раунда: число мин (D-019). */
23	export interface MinesParams {
24	  /** Число мин, целое от 1 до 24. */
25	  mines: number;
26	}
27	
28	/** Чем закончился раунд: мина, cashout или открыты все безопасные клетки. */
29	export type MinesOutcome = 'mine' | 'cashout' | 'cleared';
30	
31	/** Состояние раунда (spec, раздел «Результат и выплата»). Число мин — `mines.length` (D-022). */
32	export interface MinesState {
33	  /** Клетки с минами, по возрастанию. */
34	  mines: number[];
35	  /** Открытые безопасные клетки в порядке открытия. */
36	  revealed: number[];
37	  /** Клетка с миной, на которой игрок проиграл, иначе `null`. */
38	  hit: number | null;
39	  /** Исход раунда, `null` пока раунд открыт. */
40	  outcome: MinesOutcome | null;
41	}
42	
43	/** Ход игрока (D-007). */
44	export type MinesAction = { type: 'reveal'; cell: number } | { type: 'cashout' };
45	
46	/** Что видит клиент (D-009). Поля `mines`, `hit`, `outcome` есть только после завершения раунда. */
47	export interface MinesView {
48	  mineCount: number;
49	  revealed: number[];
50	  multiplier: number;
51	  nextMultiplier: number | null;
52	  mines?: number[];
53	  hit?: number | null;
54	  outcome?: MinesOutcome | null;
55	}
56	
57	/** Целый биномиальный коэффициент C(n, k): на каждом шаге промежуточный результат — целое число. */
58	function binom(n: number, k: number): number {
59	  if (k < 0 || k > n) return 0;
60	  let r = 1;
61	  for (let i = 1; i <= k; i++) r = (r * (n - k + i)) / i;
62	  return r;
63	}
64	
65	/**
66	 * Множитель после `k` открытых безопасных клеток при `mineCount` минах (D-021):
67	 * `M(0) = 1` (только для отображения), иначе `Math.round(98 × C(25, k) / C(25 − m, k)) / 100`.
68	 */
69	export function multiplier(k: number, mineCount: number = DEFAULT_MINES): number {
70	  if (k <= 0) return 1;
71	  return Math.round((RTP_PERCENT * binom(CELL_COUNT, k)) / binom(CELL_COUNT - mineCount, k)) / 100;
72	}
73	
74	/** Число мин: целое число 1…24, без приведения типов (D-019). */
75	function isMineCount(x: unknown): x is number {
76	  return typeof x === 'number' && Number.isInteger(x) && x >= MIN_MINES && x <= MAX_MINES;
77	}
78	
79	/** Проверяет и нормализует params до любых побочных действий; лишние поля отбрасываются (D-019). */
80	function parseParams(params: unknown): MinesParams {
81	  if (params === undefined) return { mines: DEFAULT_MINES };
82	  if (typeof params !== 'object' || params === null || Array.isArray(params)) {
83	    throw new GameError('INVALID_PARAMS', 'Параметры должны быть объектом { mines }');
84	  }
85	  if (!Object.prototype.hasOwnProperty.call(params, 'mines')) return { mines: DEFAULT_MINES };
86	  const mines = (params as { mines?: unknown }).mines;
87	  if (!isMineCount(mines)) throw new GameError('INVALID_PARAMS', 'mines должно быть целым числом от 1 до 24');
88	  return { mines };
89	}
90	
91	/** Расстановка `count` мин частичной тасовкой Фишера — Йетса: ровно `count` вызовов rng (D-020). */
92	function placeMines(rng: Rng, count: number): number[] {
93	  const c = Array.from({ length: CELL_COUNT }, (_, i) => i);
94	  for (let i = 0; i < count; i++) {
95	    const j = i + Math.floor(rng.next() * (CELL_COUNT - i));
96	    const t = c[i] as number;
97	    c[i] = c[j] as number;
98	    c[j] = t;
99	  }
100	  return c.slice(0, count).sort((a, b) => a - b);
101	}
102	
103	function invalidAction(message: string): never {
104	  throw new GameError('INVALID_ACTION', message);
105	}
106	
107	/** Проверяет ход до любых изменений; возвращает нормализованное действие. */
108	function parseAction(action: unknown, state: MinesState): MinesAction {
109	  if (typeof action !== 'object' || action === null || Array.isArray(action)) {
110	    invalidAction('Ход должен быть объектом { type, cell }');
111	  }
112	  const type = (action as { type?: unknown }).type;
113	  if (type === 'cashout') {
114	    if (state.revealed.length < 1) invalidAction('Забрать выигрыш можно после первой открытой клетки');
115	    return { type: 'cashout' };
116	  }
117	  if (type === 'reveal') {
118	    const cell = (action as { cell?: unknown }).cell;
119	    if (typeof cell !== 'number' || !Number.isInteger(cell) || cell < 0 || cell >= CELL_COUNT) {
120	      invalidAction('cell должен быть целым числом от 0 до 24');
121	    }
122	    if (state.revealed.includes(cell)) invalidAction('Клетка уже открыта');
123	    return { type: 'reveal', cell };
124	  }
125	  return invalidAction('Неизвестный тип хода');
126	}
127	
128	/**
129	 * Серверный модуль «Мин».
130	 *
131	 * - `validateParams(params)` — `{ mines }` (1…24, по умолчанию 3), лишние поля отбрасываются;
132	 *   `null`, массив, строка, число и неверное `mines` → `GameError('INVALID_PARAMS')` (D-019).
133	 * - `start({ params, rng })` — повторная проверка params, затем ровно `m` вызовов `rng.next()`, шаг `continue` (D-020).
134	 * - `action({ bet, state, action })` — `reveal`/`cashout`; rng и params не используются, число мин — из `state`,
135	 *   переданный `state` не меняется (D-005…D-007, D-022, D-023).
136	 * - `publicView(state, finished)` — до конца раунда без `mines`/`hit`/`outcome` (D-009).
137	 */
138	const game: GameModule<MinesParams, MinesState, unknown> = {
139	  id: 'mines',
140	
141	  validateParams(params: unknown): MinesParams {
142	    return parseParams(params);
143	  },
144	
145	  start({ params, rng }: { bet: number; params: MinesParams; rng: Rng }): Step<MinesState> {
146	    // Всё, что может упасть, — до обращения к rng (контракт platform/sdk/types.ts).
147	    const { mines: count } = parseParams(params);
148	    const mines = placeMines(rng, count);
149	    return { status: 'continue', state: { mines, revealed: [], hit: null, outcome: null } };
150	  },
151	
152	  action({ bet, state, action }: { bet: number; params: MinesParams; state: MinesState; action: unknown; rng: Rng }): Step<MinesState> {
153	    const a = parseAction(action, state);
154	    const mines = state.mines.slice();
155	    const m = mines.length;
156	    if (a.type === 'cashout') {
157	      const revealed = state.revealed.slice();
158	      return {
159	        status: 'finished',
160	        state: { mines, revealed, hit: null, outcome: 'cashout' },
161	        payout: bet * multiplier(revealed.length, m),
162	      };
163	    }
164	    if (mines.includes(a.cell)) {
165	      return {
166	        status: 'finished',
167	        state: { mines, revealed: state.revealed.slice(), hit: a.cell, outcome: 'mine' },
168	        payout: 0,
169	      };
170	    }
171	    const revealed = [...state.revealed, a.cell];
172	    if (revealed.length >= CELL_COUNT - m) {
173	      return {
174	        status: 'finished',
175	        state: { mines, revealed, hit: null, outcome: 'cleared' },
176	        payout: bet * multiplier(revealed.length, m),
177	      };
178	    }
179	    return { status: 'continue', state: { mines, revealed, hit: null, outcome: null } };
180	  },
181	
182	  publicView(state: MinesState, finished: boolean): MinesView {
183	    const k = state.revealed.length;
184	    const m = state.mines.length;
185	    const base = { mineCount: m, revealed: state.revealed.slice(), multiplier: multiplier(k, m) };
186	    if (!finished) return { ...base, nextMultiplier: multiplier(k + 1, m) };
187	    return { ...base, nextMultiplier: null, mines: state.mines.slice(), hit: state.hit, outcome: state.outcome };
188	  },
189	};
190	
191	/** Модуль игры `mines` (`GameModule`), который платформа загружает по `manifest.json`. */
192	export default game;
193

