15	  h1 { margin: 0; font-size: 24px; }
16	  .row { display: flex; gap: 8px; align-items: center; flex-wrap: wrap; }
17	  .label { color: var(--muted); font-size: 14px; }
18	  .balance { font-size: 20px; font-weight: 600; }
19	  input, select { font: inherit; padding: 8px; }
20	  input { width: 100px; }
21	  button { font: inherit; padding: 10px 16px; border-radius: 8px; border: 1px solid var(--muted); background: transparent; color: inherit; cursor: pointer; }
22	  button:disabled { opacity: .5; cursor: default; }
23	  #play { background: var(--accent); color: #fff; border-color: var(--accent); flex: 1; font-weight: 600; }
24	  #cashout { border-color: var(--win); color: var(--win); flex: 1; font-weight: 600; }
25	  .grid { display: grid; grid-template-columns: repeat(5, 1fr); gap: 6px; perspective: 600px; }
26	  .cell { aspect-ratio: 1; padding: 0; font-size: 22px; font-weight: 700; }
27	  .cell[data-cell-state="safe"] { background: var(--win); border-color: var(--win); color: #fff; opacity: 1; }
28	  .cell[data-cell-state="hit"] { background: var(--lose); border-color: var(--lose); color: #fff; opacity: 1; }
29	  .cell[data-cell-state="mine"] { background: var(--neutral); border-color: var(--neutral); color: var(--neutral-text); opacity: 1; }
30	  /* Переворот открытой клетки: не дольше 300 мс, состояние клетки от анимации не зависит. */
31	  .cell.flip { animation: cell-flip 250ms ease-out; }
32	  @keyframes cell-flip {
33	    from { transform: rotateY(90deg); }
34	    to { transform: rotateY(0deg); }
35	  }
36	  @media (prefers-reduced-motion: reduce) {
37	    .cell.flip { animation: none; }
38	  }
39	  .stats { display: grid; grid-template-columns: 1fr 1fr 1fr; gap: 8px; text-align: center; }
40	  .stats b { display: block; font-size: 18px; }
41	  .result { text-align: center; min-height: 1.5em; font-weight: 600; }
42	  [data-state="won"] .result { color: var(--win); }
43	  [data-state="lost"] .result { color: var(--lose); }
44	  .error { color: var(--lose); min-height: 1.2em; }
45	</style>
46	</head>
47	<body>
48	<main data-testid="game" data-state="idle">
49	  <h1>Мины</h1>
50	  <div class="row"><span class="label">Баланс:</span> <span class="balance" data-testid="balance">—</span></div>
51	
52	  <div class="row">
53	    <label class="label" for="bet">Ставка</label>
54	    <input id="bet" data-testid="bet-input" type="number" step="0.01" min="1" max="10" value="1">
55	    <span class="label" id="limits"></span>
56	  </div>
