163	
164	    function showError(e) {
165	      var code = (e && e.code) || 'INTERNAL_ERROR';
166	      var text = ERROR_TEXT[code] || (e && e.message) || 'Ошибка';
167	      errorEl.textContent = code + ': ' + text;
168	    }
169	
170	    function cellStateOf(idx, revealed, mines, hit) {
171	      if (revealed.indexOf(idx) >= 0) return 'safe';
172	      if (idx === hit) return 'hit';
173	      if (mines.indexOf(idx) >= 0) return 'mine';
174	      return 'hidden';
175	    }
